      question: "Ursa Major Solar社は、取引先をシルバー、ゴールド、プラチナレベルに分類しています。シルバーまたはゴールドの取引先に新しいケースが作成されると、通常のサポートキューに入ります。取引先がプラチナレベルの場合、自動的に優先サポートキューに入ります。管理者はこれを実現するために何を使用すべきでしょうか。",
