      choices: ["1つのページレイアウト、2つのレコードタイプ、1つの選択リスト","2つのページレイアウト、1つのレコードタイプ、2つの選択リスト","2つの権限セット、1つのレコードタイプ、1つの選択リスト","1つのレコードタイプ、2つのプロファイル、1つの選択リスト"],
