      question: "Cloud Kicks社には出荷というカスタムオブジェクトがあります。この会社は取引先ページからすべての出荷アイテムを見たいのです。取引先が削除されても、出荷情報は残っていなければなりません。管理者は、出荷と取引先との間にどのようなリレーションを作成する必要がありますか。",
      choices: ["出荷には、取引先に対する主従関係が必要です。","取引先には、出荷に対する参照関係が必要です。","取引先には、出荷に対する主従関係が必要です。","出荷には、取引先に対する参照関係が必要です。"],
      answers: [3],
      explanation: `参照関係では、親レコードが削除されても子レコード(この場合は出荷情報)は残ります。このシナリオで要求される条件を満たすためには、出荷オブジェクトに取引先オブジェクトへの参照関係を設定する必要があります。これにより、取引先ページから関連するすべての出荷アイテムを見ることができ、取引先が削除されても出荷情報は保持されます。
        ※ 主従関係では、主レコード(この場合は取引先)が削除されると従レコード(出荷)も自動的に削除されます。このシナリオでは、取引先が削除されても出荷情報が残る必要があるため、このリレーションシップは要件に合いません。
        ※ この表現はやや誤解を招く可能性がありますが、リレーションシップの設定方法としては不正確です。参照関係を作成する場合は、子側から行う必要があるため、親オブジェクト(取引先)から参照関係を作成するこの記載は適切ではありません。
        ※ このオプションも主従関係を指しており、主レコードが削除された場合に従レコードも削除されるため、要件に反します。また、取引先のような標準オブジェクトは従側になることはできません。さらに、1つの取引先に紐づく多数の出荷情報を持つリレーションシップの方向も間違っています。`
