      choices: ["エスカレーションルールが、ケース作成時にケースの所有者を変更しています。","割り当てルールのチェックボックスがデフォルトで選択されている。","別の割り当てルールが管理者に所有権を与えている。","Webフォームとメールテンプレートに所有者項目がありません。"],
