      question: "Ursa Major Solar社の管理者は、作業項目とプロジェクトというカスタムオブジェクトのリレーションシップを主従関係から参照関係に変更するよう求められました。管理者がこの要件を満たすことを妨げる可能性のあるシナリオはどれですか。",
      choices: ["レコードの保存するために参照関係が必要です。","主オブジェクトに積み上げ集計項目が含まれている。","結合オブジェクトは参照関係を作成するために必要です。","すべてのレコードの参照関係に値が含まれている必要がある。"],
      answers: [1],
      explanation: `積み上げ集計項目は、主従関係においてのみ利用可能です。もし主オブジェクトに積み上げ集計項目が存在する場合、リレーションシップを参照関係に変更することはできません。したがって、積み上げ集計項目があることが、リレーションシップの変更を妨げる可能性があります。
        ※ レコード保存時の制約は今回のシナリオと関係ありません。また、リレーションシップを変更するために参照関係ではありません。
        ※ 結合オブジェクトは、多対多のリレーションシップを作成するために使用されますが、参照関係のリレーションシップを作成するためには必要ありません。このシナリオはリレーションシップの変更に影響を与えません。
        ※ 参照関係から主従関係へのリレーションの変更には、すべてのレコードの参照項目に値が含まれている必要がありますが、主従関係から参照関係へのリレーションの変更の場合には、必要ではありません。`
