      question: "Ursa Major Solar社は、太陽光発電製品の売上を追跡するために商談を利用しています。同社には、異なるエネルギー市場に特化した2つの営業チームがあります。サービスチームもまた、商談を使用して設置を追跡したいと考えています。3つのチームはすべて、異なる項目とフェーズを使用する必要があります。管理者は、この要件をどのように構成する必要がありますか。",
      choices: ["セールスプロセスを3つ作成する。3つのレコードタイプと1つのページレイアウトを作成する。","セールスプロセスを1つ作成する。3つのレコードタイプと3つのページレイアウトを作成する。","セールスプロセスを3つ作成する。3つのレコードタイプと3つのページレイアウトを作成する。","セールスプロセスを1つ作成する。1つのレコードタイプと3つのページレイアウトを作成する。"],
      answers: [2],
      explanation: `Ursa Major Solar社の要件をまとめると以下の通りです。 異なるエネルギー市場に特化した2つの営業チームと1つのサービスチームの合計3チームあり、それぞれが商談を使用して異なる項目とフェーズで管理する必要がある。 Ursa Major Solar社の要件に基づき、管理者は以下のように構成する必要があります。 セールスプロセスの作成セールスプロセスは、営業サイクルを管理するために使用されるカスタマイズされた商談フェーズの値を持ちます。今回は、異なる商談フェーズを使用する必要があるため、3つの異なるセールスプロセスを作成します。これにより、各チームはそれぞれの営業プロセスに適したフェーズを使用できます。レコードタイプの作成商談レコードタイプには、セールスプロセスを設定することが必須です。各チームに対応する3つのセールスプロセスを紐づけるために、3つの商談レコードタイプを作成します。これにより、各レコードタイプがそれぞれのセールスプロセスに対応します。ページレイアウトの作成各チームは異なる項目を使用する必要があるため、3つの異なるページレイアウトを作成します。各ページレイアウトは、それぞれのレコードタイプに対応し、チームごとに必要な項目を表示します。`
