      choices: ["割引額を記録するために、商談にカスタム割引額項目を作成する。","営業ユーザーのユーザー詳細ページの、マネージャーという標準項目を設定する。","2つの別々の承認プロセスを構成する。","提出者が承認者を手動で選択できるようにする。"],
