      question: "Northern Trail Outfitters社のユーザーが Salesforce にログインできません。このユーザーのログイン履歴によると、このユーザーは何度もログインを試み、組織からロックアウトされています。管理者は、このユーザーがSalesforceにログインするのを支援するための手段はどれですか。2つ選びなさい。",
      choices: ["ユーザーとしてログインし、ロックを解除してパスワードをリセットする。","パスワードポリシーをリセットして、ユーザーがログインできるようにする。","ユーザーのレコード詳細ページでパスワードをリセットする。","ユーザーのレコード詳細ページの[ロック解除]ボタンを使用する。"],
