  "explanation": "四半期売上予測を使用しているときの開始月変更は、目標値や調整額の削除に影響します。保全と再設定を計画します。また、カスタム会計年度は機能を有効化すると無効化できません。最初のカスタム年度を定義するときにも予測データへの影響があります。有効化だけと年度定義を同じ操作と扱わず、基になる商談データまで消えると誤解しないようにします。\n        ※ 開始月の変更では、目標値と調整額が新期間へ再配分される：この四半期売上予測の条件では目標値と調整額が削除されます。自動で期間移行すると仮定しません。\n        ※ 売上予測の期間を変えると、元の商談レコードも削除される：目標値・調整額の削除と、基になる商談データの削除は別です。\n        ※ カスタム会計年度は、年度定義を削除すれば機能を無効化できる：年度定義の操作によって、有効化済みの機能を標準会計年度へ戻すことはできません。"
