  "explanation": "公式のベストプラクティスは、似たアクションをすべて同じ動詞で始めるより、Get、Find、Identify、Retrieveなどの処理に合った関連動詞を使い分けることを勧めています。名前と指示で機能を区別し、会話テストで期待したアクションが選ばれるか確認します。動詞を無作為に変えればよい、という意味ではありません。\n        ※ すべてのアクション名にSalesforceという共通の接頭語を付ける。：共通の製品名を繰り返しても、各アクションの機能の違いを説明できません。\n        ※ アクション名から動詞を削除し、対象名だけで区別する。：対象名だけでは何を行う処理なのかが分かりにくくなります。\n        ※ 似たアクションをすべてGetで始め、処理の違いは指示にだけ書く。：指示の改善も重要ですが、公式は名前にも異なる適切な動詞を用い、似たアクションを区別することを勧めています。"
